class Solution {
    public double average(int[] salary) {
        long sum = 0;
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        for (int s : salary) {
            sum += s;
            mn = Math.min(mn, s);
            mx = Math.max(mx, s);
        }
        return (double)(sum - mn - mx) / (salary.length - 2);
    }
}
