Compute `f` for every word and count how many words have each frequency. Since every string has length at most 10, `f` is always between 1 and 10.

Build a suffix count array where `cnt[k]` is the number of words with `f >= k`. For a query with value `fq`, the answer is `cnt[fq + 1]`, the number of words whose `f` is strictly greater.

To compute `f(s)` safely, consider only lowercase letters. This also ignores any stray spaces that appear in the examples.

```java
class Solution {
    private int f(String s) {
        char min = '{';
        int c = 0;
        for (char ch : s.toCharArray()) {
            if (ch < 'a' || ch > 'z') continue;
            if (ch < min) { min = ch; c = 1; }
            else if (ch == min) c++;
        }
        return c;
    }
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int[] cnt = new int[13];
        for (String w : words) {
            int v = f(w);
            if (v > 11) v = 11;
            cnt[v]++;
        }
        for (int i = 11; i >= 0; i--) cnt[i] += cnt[i + 1];
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int v = f(queries[i]);
            res[i] = v + 1 <= 12 ? cnt[Math.min(v + 1, 12)] : 0;
        }
        return res;
    }
}
```

