class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int m = 2 * numSlots;
        int n = nums.length;
        int[] dp = new int[1 << m];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;
        int ans = 0;
        for (int mask = 0; mask < (1 << m); mask++) {
            if (dp[mask] < 0) continue;
            int i = Integer.bitCount(mask);
            if (i == n) {
                ans = Math.max(ans, dp[mask]);
