            for (int j = 0; j < m; j++) {
                if ((mask & (1 << j)) != 0) continue;
                int nm = mask | (1 << j);
                int v = dp[mask] + (nums[i] & (j / 2 + 1));
                if (v > dp[nm]) dp[nm] = v;
            }
        }
        return ans;
    }
}
