class Solution {
    public int maxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int n = nums.length;
        int[] p = new int[n + 1];
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + nums[i];
        return Math.max(solve(p, n, firstLen, secondLen), solve(p, n, secondLen, firstLen));
    }

