class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;
        long[] f = new long[n];
        for (int i = 0; i < n; i++) f[i] = Math.min(flowers[i], target);
        java.util.Arrays.sort(f);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + f[i];
        long best = 0;
        long cost = 0;
        int p = n;
        for (int i = n; i >= 0; i--) {
            if (i < n) {
                cost += target - f[i];
                if (cost > newFlowers) break;
            }
            if (i == 0) {
                best = Math.max(best, (long) n * full);
                break;
            }
            if (f[i - 1] == target) continue;
            long rem = newFlowers - cost;
            if (p > i) p = i;
            while (p > 0 && f[p - 1] * p - prefix[p] > rem) p--;
            long mn = Math.min((long) target - 1, (prefix[p] + rem) / p);
            long cand = (long) (n - i) * full + mn * partial;
            best = Math.max(best, cand);
        }
        return best;
    }
}
