class Solution {
    public int minOperations(String s) {
        int cnt = 0, n = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != '0' && c != '1') continue;
            char expected = (n % 2 == 0) ? '0' : '1';
            if (c != expected) cnt++;
            n++;
        }
        return Math.min(cnt, n - cnt);
    }
}
