    int[][] g;
    boolean[][] vis;

    private int count() {
        vis = new boolean[m][n];
        int c = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (g[i][j] == 1 && !vis[i][j]) {
                    c++;
                    dfs(i, j);
                }
        return c;
    }

    private void dfs(int i, int j) {
        if (i < 0 || j < 0 || i >= m || j >= n || g[i][j] == 0 || vis[i][j]) return;
        vis[i][j] = true;
        dfs(i + 1, j);
        dfs(i - 1, j);
        dfs(i, j + 1);
        dfs(i, j - 1);
