```java
import java.util.*;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        Comparator<Integer> cmp = (a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b);
        TreeSet<Integer> lo = new TreeSet<>(cmp);
        TreeSet<Integer> hi = new TreeSet<>(cmp);
        int n = nums.length;
        double[] res = new double[n - k + 1];
        for (int i = 0; i < n; i++) {
            lo.add(i);
            hi.add(lo.pollLast());
            if (hi.size() > lo.size()) lo.add(hi.pollFirst());
            if (i >= k) {
                int j = i - k;
                if (!lo.remove(j)) hi.remove(j);
                while (lo.size() < hi.size()) lo.add(hi.pollFirst());
                while (lo.size() > hi.size() + 1) hi.add(lo.pollLast());
            }
            if (i >= k - 1) {
                if (k % 2 == 1) {
                    res[i - k + 1] = nums[lo.last()];
                } else {
                    res[i - k + 1] = ((double) nums[lo.last()] + (double) nums[hi.first()]) / 2.0;
                }
            }
        }
        return res;
    }
}
