class Solution {
    int[][][] memoMin = new int[29][29][29];
    int[][][] memoMax = new int[29][29][29];

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        int[] r = solve(n, firstPlayer, secondPlayer);
        return r;
    }

    private int[] solve(int n, int a, int b) {
        if (a + b == n + 1) return new int[]{1, 1};
        if (memoMin[n][a][b] != 0) return new int[]{memoMin[n][a][b], memoMax[n][a][b]};
        int half = n / 2;
        int[] fi = new int[half], fj = new int[half];
        int k = 0;
        boolean[] fixedAlive = new boolean[n + 2];
        for (int i = 1; i <= half; i++) {
            int j = n + 1 - i;
            if (i == a || i == b) fixedAlive[i] = true;
            else if (j == a || j == b) fixedAlive[j] = true;
            else { fi[k] = i; fj[k] = j; k++; }
        }
        if (n % 2 == 1) fixedAlive[(n + 1) / 2] = true;
        int m = (n + 1) / 2;
        int best = Integer.MAX_VALUE, worst = Integer.MIN_VALUE;
        boolean[] alive = new boolean[n + 2];
        for (int mask = 0; mask < (1 << k); mask++) {
            for (int x = 1; x <= n; x++) alive[x] = fixedAlive[x];
            for (int t = 0; t < k; t++) {
                if (((mask >> t) & 1) == 1) alive[fi[t]] = true;
                else alive[fj[t]] = true;
            }
            int na = 0, nb = 0, cnt = 0;
            for (int x = 1; x <= n; x++) {
                if (alive[x]) {
                    cnt++;
                    if (x == a) na = cnt;
                    if (x == b) nb = cnt;
                }
            }
            int[] r = solve(m, na, nb);
            best = Math.min(best, r[0] + 1);
            worst = Math.max(worst, r[1] + 1);
        }
        memoMin[n][a][b] = best;
        memoMax[n][a][b] = worst;
        return new int[]{best, worst};
    }
}
